"""One-page situation report (brief "OUTPUT": "a one-page situation report generated by the
system"), built ONLY from results.json, no language model.

Outputs in <run>/report/: sitrep.pdf (A4), sitrep.png (same page), sitrep.txt (plain text for
radio/SMS relay). Every number is read from the results dictionary; a stage that did not
run shows "not available" with its reason instead of a number. Wording never claims
certainty ("potentially affected", "likely cut off … verify on the ground").
"""

from __future__ import annotations

import textwrap
from pathlib import Path
from typing import Any

import matplotlib

matplotlib.use("Agg")
import matplotlib.image as mpimg  # noqa: E402
import matplotlib.pyplot as plt  # noqa: E402

from sampark import attribution  # noqa: E402

A4 = (8.27, 11.69)
PNG_DPI = 130
NAVY, GREY, RED = "#16324f", "#555555", "#b2182b"


def _stage(results: dict, name: str) -> dict | None:
    st = results.get("stages", {}).get(name)
    return st if st and st.get("status") in ("ok", "partial") else None


def _why_missing(results: dict, name: str) -> str:
    st = results.get("stages", {}).get(name)
    return f"not available ({st.get('message', 'not run')[:70]})" if st else "not available"


def safe_name(name: str | None, lat: float | None = None, lon: float | None = None) -> str:
    """Latin-script name for the PDF font; local-script names fall back to coordinates."""
    if isinstance(name, str) and name.isascii():
        return name
    if lat is not None and lon is not None:
        return f"settlement at {lat:.3f}N {lon:.3f}E"
    return "settlement (local-script name)"


def _fmt(v: Any, unit: str = "", digits: int = 0) -> str:
    if v is None:
        return "n/a"
    if isinstance(v, int | float):
        return f"{v:,.{digits}f}{unit}"
    return str(v)


def key_figures(results: dict) -> list[tuple[str, str]]:
    """(label, value) rows; every value comes from results.json."""
    rows: list[tuple[str, str]] = []
    conf = _stage(results, "confidence")
    if conf:
        o = conf["outputs"]
        c = o.get("affected_by_confidence_km2", {})
        rows.append(("Area potentially affected (flood/debris)",
                     f"{_fmt(o.get('affected_total_km2'), ' km²', 2)}  (high "
                     f"{_fmt(c.get('high'), '', 2)} · medium {_fmt(c.get('medium'), '', 2)} · "
                     f"low {_fmt(c.get('low'), '', 2)})"))
    else:
        rows.append(("Area potentially affected", _why_missing(results, "confidence")))
    dmg = _stage(results, "damage")
    if dmg:
        o = dmg["outputs"]
        b = o.get("buildings", {})
        rows += [
            ("Buildings potentially affected",
             f"{_fmt(b.get('potentially_affected'))} of {_fmt(b.get('of_total_in_area'))} "
             f"(high confidence {_fmt(b.get('by_confidence', {}).get('high'))})"),
            ("Motorable road in flood/debris",
             f"{_fmt(o.get('roads', {}).get('affected_km_motorable'), ' km', 1)}"),
            ("Bridges potentially affected",
             f"{_fmt(o.get('bridges', {}).get('potentially_affected'))}"),
            ("Health facilities potentially affected", f"{len(o.get('health_facilities', []))}"),
        ]
    else:
        rows.append(("Damage overlay", _why_missing(results, "damage")))
    cut = _stage(results, "cutoff")
    if cut:
        m = cut["outputs"].get("by_network", {}).get("motorable", {})
        f = cut["outputs"].get("by_network", {}).get("all_ways", {})
        rows += [
            ("Settlements likely cut off by road",
             f"{_fmt(m.get('likely cut off'))} ({_fmt(m.get('buildings_in_cut_off_settlements'))}"
             f" buildings); possibly {_fmt(m.get('possibly cut off'))}"),
            ("…of which no mapped footpath either", f"{_fmt(f.get('likely cut off'))}"),
            ("Likely lost road access to every hospital", f"{_fmt(m.get('lost_hospital_access'))}"),
        ]
    else:
        rows.append(("Cut-off analysis", _why_missing(results, "cutoff")))
    return rows


def data_line(results: dict) -> str:
    parts = []
    s1 = _stage(results, "s1")
    if s1:
        tracks = s1["outputs"].get("tracks", [])
        parts.append("Sentinel-1 " + "; ".join(
            f"{t['pair']['track']} after {t['pair']['post']['start_utc'][:10]}" for t in tracks))
    s2 = _stage(results, "s2")
    parts.append("Sentinel-2 " + (s2["message"].split(":")[0].replace("Sentinel-2 ", "")
                                  if s2 else "not used (cloud or not available)"))
    osm = _stage(results, "osm")
    if osm:
        parts.append(f"OSM pre-event snapshot {osm['outputs'].get('snapshot_utc', '')[:10]}")
    parts.append("Copernicus DEM GLO-30")
    return " · ".join(parts)


def priorities(results: dict, n: int = 7) -> list[str]:
    pri = _stage(results, "priority")
    if not pri:
        return [_why_missing(results, "priority")]
    out = []
    for e in pri["outputs"].get("top", [])[:n]:
        reasons = "; ".join(e.get("reasons", [])[:2])
        out.append(f"{e['rank']}. {safe_name(e.get('name'), e.get('lat'), e.get('lon'))} "
                   f"({_fmt(e.get('buildings'))} buildings): {reasons}")
    return out or ["no settlement meets the priority criteria"]


def breaks(results: dict, n: int = 5) -> list[str]:
    cut = _stage(results, "cutoff")
    if not cut:
        return [_why_missing(results, "cutoff")]
    rows = [f"{b['road']} at {b['lat']:.3f}N {b['lon']:.3f}E: cuts off "
            f"{b['settlements_cut_off']} settlements ({_fmt(b['buildings_cut_off'])} buildings)"
            for b in cut["outputs"].get("key_breaks", [])[:n]]
    return rows or ["no likely road break detected"]


def flood_path_line(results: dict) -> list[str]:
    fp = _stage(results, "flood_path")
    if not fp:
        return []
    o = fp["outputs"]
    low = [s for s in (o.get("settlements_along_path") or []) if s.get("low_lying")]
    head = (f"Traced {_fmt(o.get('length_km'), ' km', 1)} downstream; low-lying settlements "
            f"(≤ HAND limit above the river):")
    names = ", ".join(f"{safe_name(s['name'], s.get('lat'), s.get('lon'))} (km "
                      f"{s['km_downstream']:.0f})" for s in low[:10]) or "none listed"
    return [head + " " + names]


def model_line(results: dict) -> list[str]:
    seg = _stage(results, "segmentation")
    if not seg:
        return []
    o = seg["outputs"]
    t = (o.get("model_test_scores") or {}).get("test") or {}
    return [f"Our own water model (U-Net, trained on Sen1Floods11): new water "
            f"{_fmt(o.get('new_water_km2'), ' km²', 2)} in the plausible zone; test IoU "
            f"{_fmt(t.get('iou'), '', 2)}. Second opinion only; weak in steep terrain."]


def landing_line(results: dict) -> list[str]:
    lz = _stage(results, "landing_zones")
    if not lz or not lz["outputs"].get("likely_cut_off_settlements"):
        return []
    o = lz["outputs"]
    missing = o["likely_cut_off_settlements"] - o["settlements_served"]
    return [f"Helicopter landing-zone candidates for {o['settlements_served']} of "
            f"{o['likely_cut_off_settlements']} settlements likely cut off "
            f"(flat, dry, clear of buildings, within "
            f"{o['criteria']['max_distance_m'] / 1000:g} km); none found for {missing} "
            "(steep terrain). Candidates only: verify trees, wires and ground on site."]


def multidate_line(results: dict) -> list[str]:
    md = _stage(results, "multidate")
    if not md:
        return []
    o = md["outputs"]
    t, c = o["timeline"], o["changes_first_to_last"]
    lakes = o.get("possible_lakes", [])
    text = (f"Later passes ({t[0]['date']} to {t[-1]['date']}): water {t[0]['water_km2']:.2f} "
            f"-> {t[-1]['water_km2']:.2f} km²; receding {c['receding_water_km2']:.2f} km², "
            f"new ponding {c['new_ponding_km2']:.2f} km².")
    if lakes:
        top = lakes[0]
        text += (f" {len(lakes)} growing water bodies flagged as POSSIBLE lakes forming (largest "
                 f"{top['area_km2_by_date'][-1]:.2f} km² at {top['lat']:.3f}N "
                 f"{top['lon']:.3f}E): verify for a debris dam.")
    return [text]


LIMITATIONS = [
    "Sentinel satellites revisit every few days: the images are 2-10 days after the event "
    "and cannot warn of a sudden collapse minutes ahead.",
    "Radar sees surface change, not damage: 'potentially affected' and 'likely cut off' "
    "need verification on the ground.",
    "Only buildings, roads and bridges mapped in OpenStreetMap before the event are counted.",
]


def _wrap(fig, renderer, text: str, fontsize: float, width_frac: float) -> list[str]:
    """Greedy word wrap by MEASURED width on the page (no guessed character counts)."""
    limit = width_frac * fig.bbox.width
    probe = fig.text(0, 0, "", fontsize=fontsize)
    lines, cur = [], ""
    for word in text.split():
        trial = f"{cur} {word}".strip()
        probe.set_text(trial)
        if cur and probe.get_window_extent(renderer).width > limit:
            lines.append(cur)
            cur = word
        else:
            cur = trial
    probe.remove()
    return lines + ([cur] if cur else [])


def _page(results, run_dir, title, head, figs, sections, footer, scale):
    """Draw the page at font `scale`; return (figure, lowest text y, top of the footer)."""
    # measured at the PNG resolution: small text changes width slightly with resolution
    fig = plt.figure(figsize=A4, dpi=PNG_DPI)
    fig.patch.set_facecolor("white")
    renderer = fig.canvas.get_renderer()
    line_h = 1.0 / (A4[1] * 72)  # one point as a fraction of the page height

    def block(x, y, text, size, width, **kw):
        lines = _wrap(fig, renderer, text, size, width)
        fig.text(x, y, "\n".join(lines), fontsize=size, va="top", linespacing=1.25, **kw)
        return y - len(lines) * size * 1.25 * line_h

    fig.text(0.04, 0.975, "SITUATION REPORT", fontsize=17, fontweight="bold", color=NAVY,
             va="top")
    fig.text(0.96, 0.975, "EDUCATIONAL PROTOTYPE —\nNOT AN OPERATIONAL TOOL", fontsize=8,
             color=RED, ha="right", va="top", fontweight="bold")
    fig.text(0.04, 0.945, textwrap.fill(title, 80), fontsize=11, color=NAVY, va="top")
    block(0.04, 0.918, head, 6.5, 0.88, color=GREY)

    y = 0.885
    fig.text(0.04, y, "Key figures (estimates from satellite data)", fontsize=9.5,
             fontweight="bold", color=NAVY, va="top")
    y -= 0.02
    for label, value in figs:
        fig.text(0.04, y, label, fontsize=7.2 * scale, va="top")
        y = min(y - 7.2 * scale * 1.25 * line_h,
                block(0.31, y, value, 7.2 * scale, 0.21, fontweight="bold")) - 0.004

    map_png = _pick_map(results, run_dir)
    if map_png is not None:
        ax = fig.add_axes([0.53, 0.60, 0.44, 0.29])
        img = mpimg.imread(map_png)
        h, w = img.shape[:2]
        ax.imshow(img[:, : int(w * 0.66)])  # map panel only (the side text is in this page)
        ax.axis("off")
        ax.set_title("Map: " + map_png.parent.name + "/" + map_png.name, fontsize=6,
                     color=GREY)

    y = min(y, 0.59) - 0.01
    for header, lines in sections:
        if not lines:
            continue
        fig.text(0.04, y, header, fontsize=9.5 * scale, fontweight="bold", color=NAVY,
                 va="top")
        y -= 9.5 * scale * 1.6 * line_h
        for line in lines:
            y = block(0.05, y, "• " + line, 7 * scale, 0.88) - 0.003
        y -= 0.006
    foot = _wrap(fig, renderer, footer, 5.2, 0.88)
    fig.text(0.5, 0.012, "\n".join(foot), fontsize=5.2, color=GREY, ha="center",
             va="bottom", linespacing=1.2)
    return fig, y, 0.012 + len(foot) * 5.2 * 1.2 * line_h + 0.006


def build(results: dict, run_dir: Path, out_dir: Path) -> dict[str, Path]:
    out_dir.mkdir(parents=True, exist_ok=True)
    title = results.get("event_name", "custom area")
    aoi = results.get("aoi", {})
    head = (f"Flood date {results.get('event_date')} · area {_fmt(aoi.get('area_km2'), ' km²', 0)}"
            f" · bbox {', '.join(f'{v:.2f}' for v in aoi.get('bbox', []))} · generated "
            f"{results.get('created_utc', '')[:16].replace('T', ' ')} UTC · run "
            f"{results.get('run_id', '')}")
    figs, pris, brks = key_figures(results), priorities(results), breaks(results)
    extra = (landing_line(results) + multidate_line(results) + flood_path_line(results)
             + model_line(results))
    footer = attribution.footer_text()
    if _stage(results, "segmentation"):
        footer += " Training data: " + attribution.SEN1FLOODS11_CITATION

    # One page, always: shrink the text a little, then list fewer priorities/breaks (the
    # full lists are in the dashboard, priority.csv and the text version below).
    attempts = [(sc, len(pris), len(brks)) for sc in (1.0, 0.93, 0.86)]
    attempts += [(0.86, n, min(len(brks), 3)) for n in range(len(pris) - 1, 2, -1)]
    for scale, n_pri, n_brk in attempts + [(0.8, min(len(pris), 3), min(len(brks), 3))]:
        sections = (("Rescue priorities (tier, then affected buildings)", pris[:n_pri]),
                    ("Key road / bridge breaks (likely impassable)", brks[:n_brk]),
                    ("Landing zones, later passes, flood path, AI model", extra),
                    ("Limitations", LIMITATIONS))
        fig, y_end, footer_top = _page(results, run_dir, title, head, figs, sections,
                                       footer, scale)
        if y_end >= footer_top:
            break
        plt.close(fig)
    pdf, png = out_dir / "sitrep.pdf", out_dir / "sitrep.png"
    fig.savefig(pdf)
    fig.savefig(png, dpi=PNG_DPI)
    plt.close(fig)

    txt = out_dir / "sitrep.txt"
    body = ["SITUATION REPORT (educational prototype, not an operational tool)", title, head, "",
            "KEY FIGURES (estimates):", *[f"- {a}: {b}" for a, b in figs], "",
            "RESCUE PRIORITIES:", *[f"- {p}" for p in pris], "", "KEY BREAKS:",
            *[f"- {b}" for b in brks], *(["", "LANDING ZONES / FLOOD PATH / AI MODEL:"] +
                                         [f"- {e}" for e in extra] if extra else []),
            "", "LIMITATIONS:", *[f"- {lim}" for lim in LIMITATIONS], "", footer]
    txt.write_text("\n".join(body) + "\n", encoding="utf-8")
    return {"pdf": pdf, "png": png, "txt": txt}


def _pick_map(results: dict, run_dir: Path) -> Path | None:
    for rel in ("cutoff/cutoff_map_focus.png", "cutoff/cutoff_map.png",
                "damage/damage_map_focus.png", "damage/damage_map.png",
                "confidence/flood_map_focus.png", "confidence/flood_map.png"):
        p = run_dir / rel
        if p.is_file():
            return p
    return None
